import { GoogleGenAI } from "@google/genai";
import { CapabilityStatus, DialecticalState, DialecticStyle } from "../types";

const CLOUD_MODEL_FLASH = 'gemini-3-flash-preview';
const CLOUD_MODEL_PRO = 'gemini-3-pro-preview';

const STYLES = {
  chola: {
    name: "CHOLA (Root/Barrio)",
    keywords: "barrio, authentic, resistance, identity, urban wisdom",
    tone: "raw, direct, grounded in reality"
  },
  malandra: {
    name: "MALANDRA (Strategy/Survival)",
    keywords: "cunning, street smarts, strategy, adaptation, survival",
    tone: "sharp, critical, strategic, disruptive"
  },
  fresa: {
    name: "FRESA (Tech/Refined)",
    keywords: "refined, aesthetic, technological, innovative, elite",
    tone: "polished, academic, high-tech, aspirational"
  },
  hybrida: {
    name: "SALAMANDRA (Magistral Decodificadora)",
    keywords: "master decoding, alchemy, 369, transformation, synthesis",
    tone: "visionary, integrating, fluid, magistral, quantum"
  }
};

export class ChalamandraEngine {
  private genAI: GoogleGenAI;
  private apiKey: string;
  private capabilities: CapabilityStatus = {
    languageModel: 'unavailable',
    summarizer: 'unavailable',
    writer: 'unavailable',
    rewriter: 'unavailable',
    proofreader: 'unavailable'
  };

  constructor() {
    this.apiKey = process.env.API_KEY || '';
    this.genAI = new GoogleGenAI({ apiKey: this.apiKey });
  }

  setApiKey(key: string) {
    this.apiKey = key;
    if (this.apiKey) {
      this.genAI = new GoogleGenAI({ apiKey: this.apiKey });
    }
  }

  async checkCapabilities(): Promise<CapabilityStatus> {
    if (typeof window === 'undefined' || !window.ai) {
      this.resetCapabilities();
      return this.capabilities;
    }

    const ai = window.ai;
    const cloudFallback = this.apiKey ? 'cloud' : 'unavailable';

    const getStatus = async (factory: any): Promise<'local' | 'cloud' | 'unavailable'> => {
      if (!factory || typeof factory.capabilities !== 'function') return cloudFallback;
      try {
        const cap = await factory.capabilities();
        return (cap.available === 'readily' || cap.available === 'after-download') ? 'local' : cloudFallback;
      } catch { return cloudFallback; }
    };

    this.capabilities = {
      languageModel: await getStatus(ai.languageModel),
      summarizer: await getStatus(ai.summarizer),
      writer: await getStatus(ai.writer),
      rewriter: await getStatus(ai.rewriter),
      proofreader: await getStatus(ai.proofreader)
    };
    return this.capabilities;
  }

  private resetCapabilities() {
    this.capabilities = { languageModel: 'unavailable', summarizer: 'unavailable', writer: 'unavailable', rewriter: 'unavailable', proofreader: 'unavailable' };
  }

  async runDialectic(
    input: string, 
    thesisStyle: DialecticStyle = 'chola',
    antithesisStyle: DialecticStyle = 'malandra',
    onProgress?: (stage: string) => void
  ): Promise<DialecticalState> {

    onProgress?.(`Generating Thesis: ${STYLES[thesisStyle].name}...`);
    const thesisResult = await this.generateThesis(input, thesisStyle);

    onProgress?.(`Generating Antithesis: ${STYLES[antithesisStyle].name}...`);
    const antithesis = await this.generateAntithesis(input, thesisResult.text, antithesisStyle);

    onProgress?.('Decodificando: SALAMANDRA MAGISTRAL...');
    const synthesis = await this.generateSynthesis(input, thesisResult.text, antithesis);

    return { 
      thesis: thesisResult.text,
      thesisSources: thesisResult.sources,
      antithesis, 
      synthesis, 
      energySignature: `${thesisStyle}-${antithesisStyle}-salamandra`
    };
  }

  async generateDisruption(input: string): Promise<string> {
    const prompt = `Apply CREATIVE DISRUPTION level 9/10 to: "${input}". Rules: Inverse Mechanics, Order to Chaos. High-impact output.`;
    const result = await this.callCloud(CLOUD_MODEL_PRO, prompt);
    return result.text;
  }

  private async generateThesis(input: string, styleKey: DialecticStyle): Promise<{ text: string, sources?: string[] }> {
    const style = STYLES[styleKey];
    const context = `Role: ${style.name}. Tone: ${style.tone}.`;
    const prompt = `${context}\nInput: "${input}"\nProvide a fact-based Thesis.`;
    return this.callCloud(CLOUD_MODEL_FLASH, prompt, { tools: [{ googleSearch: {} }] });
  }

  private async generateAntithesis(input: string, thesis: string, styleKey: DialecticStyle): Promise<string> {
    const style = STYLES[styleKey];
    const prompt = `Role: ${style.name}. Challenge the following Thesis: "${thesis}" regarding "${input}".`;
    const result = await this.callCloud(CLOUD_MODEL_FLASH, prompt);
    return result.text;
  }

  private async generateSynthesis(input: string, thesis: string, antithesis: string): Promise<string> {
    const prompt = `As SALAMANDRA (Master Decoder), fuse the Thesis: "${thesis}" and Antithesis: "${antithesis}" into a quantum synthesis for "${input}".`;
    const result = await this.callCloud(CLOUD_MODEL_PRO, prompt);
    return result.text;
  }

  private async callCloud(modelName: string, prompt: string, config?: any): Promise<{ text: string, sources?: string[] }> {
    if (!this.apiKey) return { text: "⚠️ Gemini API Key required." };
    try {
      const ai = new GoogleGenAI({ apiKey: this.apiKey });
      const response = await ai.models.generateContent({
        model: modelName,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: config
      });

      const text = response.text || "No response.";
      const sources: string[] = [];
      response.candidates?.[0]?.groundingMetadata?.groundingChunks?.forEach((chunk: any) => {
        if (chunk.web?.uri) sources.push(chunk.web.uri);
      });

      return { text, sources: sources.length > 0 ? sources : undefined };
    } catch (error) {
      console.error(error);
      return { text: "Cloud Error: Verify connection." };
    }
  }
}

export const chalamandra = new ChalamandraEngine();

import React, { useState, useEffect, useCallback } from 'react';
import { ChalamandraEngine } from './services/chalamandraService';
import { DialecticalState, ProcessingStatus, CapabilityStatus, DialecticStyle, DisruptionResult } from './types';
import { Loader2, BrainCircuit, Zap, Sparkles, Cpu, Cloud, WifiOff, Settings, Key, X, Shuffle, Link as LinkIcon, ExternalLink } from 'lucide-react';

const engine = new ChalamandraEngine();

const App: React.FC = () => {
  const [apiKey, setApiKey] = useState('');
  const [input, setInput] = useState('');
  const [result, setResult] = useState<DialecticalState | null>(null);
  const [disruption, setDisruption] = useState<DisruptionResult | null>(null);
  const [status, setStatus] = useState<ProcessingStatus>({ step: 'idle' });
  const [capabilities, setCapabilities] = useState<CapabilityStatus | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [thesisStyle, setThesisStyle] = useState<DialecticStyle>('chola');
  const [antithesisStyle, setAntithesisStyle] = useState<DialecticStyle>('malandra');

  useEffect(() => {
    if (typeof chrome !== 'undefined' && chrome.storage) {
      chrome.storage.sync.get(['geminiApiKey', 'preferredThesis', 'preferredAntithesis'], (res) => {
        if (res.geminiApiKey) {
          setApiKey(res.geminiApiKey);
          engine.setApiKey(res.geminiApiKey);
        }
        if (res.preferredThesis) setThesisStyle(res.preferredThesis);
        if (res.preferredAntithesis) setAntithesisStyle(res.preferredAntithesis);
      });

      chrome.storage.local.get(['lastSelectedText'], (res) => {
        if (res.lastSelectedText) {
          setInput(res.lastSelectedText);
          chrome.storage.local.remove(['lastSelectedText']);
        }
      });
    }
    engine.checkCapabilities().then(setCapabilities);
  }, []);

  const saveSettings = () => {
    if (typeof chrome !== 'undefined' && chrome.storage) {
      chrome.storage.sync.set({ 
        geminiApiKey: apiKey,
        preferredThesis: thesisStyle,
        preferredAntithesis: antithesisStyle
      });
    }
    engine.setApiKey(apiKey);
    engine.checkCapabilities().then(setCapabilities);
    setShowSettings(false);
  };

  const handleAnalyze = async () => {
    if (!input.trim()) return;
    setResult(null);
    setDisruption(null);
    setStatus({ step: 'analyzing_thesis' });

    try {
      const dialectic = await engine.runDialectic(input, thesisStyle, antithesisStyle, (msg) => {
        setStatus(prev => ({ ...prev, message: msg }));
      });
      setResult(dialectic);
      setStatus({ step: 'complete' });
    } catch {
      setStatus({ step: 'error', message: 'Quantum Collapse' });
    }
  };

  const handleDisrupt = async () => {
    if (!input.trim()) return;
    setStatus({ step: 'disrupting', message: 'Disrupting Reality...' });
    try {
      const text = await engine.generateDisruption(input);
      setDisruption({ original: input, disrupted: text, level: 9 });
      setStatus({ step: 'complete' });
    } catch {
      setStatus({ step: 'error' });
    }
  };

  const StatusIcon = ({ status }: { status: 'local' | 'cloud' | 'unavailable' }) => {
    if (status === 'local') return <Cpu className="w-3 h-3 text-emerald-400" />;
    if (status === 'cloud') return <Cloud className="w-3 h-3 text-sky-400" />;
    return <WifiOff className="w-3 h-3 text-slate-500" />;
  };

  return (
    <div className="min-h-full bg-void text-slate-100 p-4 font-sans selection:bg-hybrida selection:text-white relative overflow-x-hidden">
      <div className="space-y-6 relative z-10">
        <header className="flex justify-between items-end border-b border-white/10 pb-4">
          <div>
            <h1 className="text-3xl font-black tracking-tighter bg-gradient-to-r from-chola via-malandra to-fresa bg-clip-text text-transparent uppercase">
              Chalamandra
            </h1>
            <p className="text-malandra font-mono text-[9px] tracking-widest uppercase opacity-80">Magistral Decodificadora 369</p>
          </div>
          <div className="flex flex-col items-end gap-2">
            <button onClick={() => setShowSettings(!showSettings)} className="p-1.5 hover:bg-white/10 rounded-full text-slate-400">
              <Settings className="w-4 h-4" />
            </button>
            {capabilities && (
              <div className="glass-panel px-2 py-1 rounded-lg flex gap-2 text-[8px] font-mono text-slate-400">
                <span className="flex items-center gap-1"><StatusIcon status={capabilities.languageModel} /> LLM</span>
                <span className="flex items-center gap-1"><StatusIcon status={capabilities.summarizer} /> SUM</span>
              </div>
            )}
          </div>
        </header>

        {showSettings && (
          <div className="glass-panel p-4 rounded-xl border border-white/10 bg-[#1A1A2E]/95 animate-in slide-in-from-top-4">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-xs font-bold uppercase tracking-widest flex items-center gap-2"><Key className="w-3 h-3" /> API Config</h3>
              <button onClick={() => setShowSettings(false)}><X className="w-4 h-4" /></button>
            </div>
            <input 
              type="password" 
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
              placeholder="Gemini API Key..."
              className="w-full bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-xs font-mono mb-3 focus:border-malandra outline-none"
            />
            <button onClick={saveSettings} className="w-full bg-malandra text-black font-bold text-xs py-2 rounded-lg hover:opacity-90 uppercase">
              Save & Synchronize
            </button>
          </div>
        )}

        <section className="space-y-4">
          <textarea
            className="w-full h-24 bg-[#141424] border border-white/10 rounded-xl p-3 text-sm focus:ring-1 focus:ring-hybrida outline-none transition-all placeholder:text-slate-600 resize-none font-light"
            placeholder="Introduce un concepto o dilema..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />

          <div className="grid grid-cols-2 gap-2">
            <div className="glass-panel rounded-lg p-2 flex flex-col gap-1 border-l-2 border-chola">
              <label className="text-[8px] font-mono text-chola uppercase">Thesis Style</label>
              <select value={thesisStyle} onChange={(e) => setThesisStyle(e.target.value as DialecticStyle)} className="bg-transparent text-[10px] font-bold outline-none cursor-pointer">
                <option value="chola">CHOLA (Root)</option>
                <option value="malandra">MALANDRA (Strat)</option>
                <option value="fresa">FRESA (Tech)</option>
              </select>
            </div>
            <div className="glass-panel rounded-lg p-2 flex flex-col gap-1 border-l-2 border-malandra">
              <label className="text-[8px] font-mono text-malandra uppercase">Antithesis Style</label>
              <select value={antithesisStyle} onChange={(e) => setAntithesisStyle(e.target.value as DialecticStyle)} className="bg-transparent text-[10px] font-bold outline-none cursor-pointer">
                <option value="malandra">MALANDRA (Strat)</option>
                <option value="fresa">FRESA (Tech)</option>
                <option value="chola">CHOLA (Root)</option>
              </select>
            </div>
          </div>

          <div className="flex gap-2">
            <button
              onClick={handleAnalyze}
              disabled={status.step !== 'idle' && status.step !== 'complete'}
              className="flex-1 bg-gradient-to-r from-chola to-malandra text-white font-bold rounded-lg py-2.5 flex items-center justify-center gap-2 shadow-lg text-xs disabled:opacity-50"
            >
              {status.step.includes('analyzing') ? <Loader2 className="animate-spin w-3 h-3" /> : <BrainCircuit className="w-3 h-3" />}
              DECODE TRILOGY
            </button>
            <button
              onClick={handleDisrupt}
              className="flex-1 border border-fresa/50 text-fresa hover:bg-fresa/10 font-bold rounded-lg py-2.5 flex items-center justify-center gap-2 text-xs"
            >
              {status.step === 'disrupting' ? <Loader2 className="animate-spin w-3 h-3" /> : <Shuffle className="w-3 h-3" />}
              DISRUPT
            </button>
          </div>
        </section>

        {(result || disruption) && (
          <div className="space-y-4 pb-8 animate-in fade-in slide-in-from-bottom-4">
            {result && (
              <>
                <div className="glass-panel rounded-xl p-4 border-l-4 border-chola">
                  <h3 className="text-[9px] font-mono font-bold tracking-widest text-chola mb-2">TESIS</h3>
                  <p className="text-xs text-slate-300 leading-relaxed">{result.thesis}</p>
                  {result.thesisSources && (
                    <div className="mt-3 flex flex-wrap gap-2 border-t border-white/5 pt-2">
                      {result.thesisSources.map((s, i) => (
                        <a key={i} href={s} target="_blank" className="text-[8px] bg-white/5 px-2 py-1 rounded flex items-center gap-1 hover:bg-white/10 truncate max-w-[120px]">
                          <ExternalLink className="w-2 h-2" /> {new URL(s).hostname}
                        </a>
                      ))}
                    </div>
                  )}
                </div>
                <div className="glass-panel rounded-xl p-4 border-l-4 border-malandra">
                  <h3 className="text-[9px] font-mono font-bold tracking-widest text-malandra mb-2">ANTÍTESIS</h3>
                  <p className="text-xs text-slate-300 leading-relaxed">{result.antithesis}</p>
                </div>
                <div className="glass-panel rounded-xl p-4 border-l-4 border-hybrida bg-gradient-to-br from-hybrida/10 to-transparent quantum-glow">
                  <h3 className="text-[9px] font-mono font-bold tracking-widest text-hybrida mb-2">SÍNTESIS SALAMANDRA</h3>
                  <p className="text-xs text-white font-medium leading-relaxed">{result.synthesis}</p>
                  <Sparkles className="absolute top-2 right-2 w-4 h-4 text-hybrida/30 animate-pulse-slow" />
                </div>
              </>
            )}
            {disruption && (
              <div className="glass-panel rounded-xl p-4 border border-fresa/30 bg-fresa/5">
                <h3 className="text-xs font-black text-fresa flex items-center gap-2 mb-2"><Zap className="w-3 h-3" /> DISRUPTION LVL 9</h3>
                <p className="text-xs italic text-slate-400 mb-2">"{disruption.original}"</p>
                <p className="text-sm font-bold text-white border-l-2 border-fresa pl-3">{disruption.disrupted}</p>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

