    const synthesis = await this.generateSynthesis(input, thesisResult.text, antithesis);

    return { 
      thesis: thesisResult.text,
      thesisSources: thesisResult.sources,
      antithesis, 
      synthesis, 
      energySignature: `${thesisStyle}-${antithesisStyle}-salamandra`
    };
  }

  async generateDisruption(input: string): Promise<string> {
    const prompt = `Apply CREATIVE DISRUPTION level 9/10 to: "${input}". Rules: Inverse Mechanics, Order to Chaos. High-impact output.`;
    const result = await this.callCloud(CLOUD_MODEL_PRO, prompt);
    return result.text;
  }

  private async generateThesis(input: string, styleKey: DialecticStyle): Promise<{ text: string, sources?: string[] }> {
    const style = STYLES[styleKey];
    const context = `Role: ${style.name}. Tone: ${style.tone}.`;
    const prompt = `${context}\nInput: "${input}"\nProvide a fact-based Thesis.`;
    // Fix: Use googleSearch tool in config
    return this.callCloud(CLOUD_MODEL_FLASH, prompt, { tools: [{ googleSearch: {} }] });
  }

  private async generateAntithesis(input: string, thesis: string, styleKey: DialecticStyle): Promise<string> {
    const style = STYLES[styleKey];
    const prompt = `Role: ${style.name}. Challenge the following Thesis: "${thesis}" regarding "${input}".`;
    const result = await this.callCloud(CLOUD_MODEL_FLASH, prompt);
    return result.text;
  }

  private async generateSynthesis(input: string, thesis: string, antithesis: string): Promise<string> {
    const prompt = `As SALAMANDRA (Master Decoder), fuse the Thesis: "${thesis}" and Antithesis: "${antithesis}" into a quantum synthesis for "${input}".`;
    const result = await this.callCloud(CLOUD_MODEL_PRO, prompt);
    return result.text;
  }

  private async callCloud(modelName: string, prompt: string, config?: any): Promise<{ text: string, sources?: string[] }> {
    if (!process.env.API_KEY) return { text: "⚠️ Gemini API Key missing from environment." };
    try {
      // Fix: Create fresh GoogleGenAI instance for each call
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: modelName,
        contents: prompt, // Fix: Use string directly for text-only prompts
        config: config
      });

      const text = response.text || "No response.";
      const sources: string[] = [];
      response.candidates?.[0]?.groundingMetadata?.groundingChunks?.forEach((chunk: any) => {
        if (chunk.web?.uri) sources.push(chunk.web.uri);
      });

      return { text, sources: sources.length > 0 ? sources : undefined };
    } catch (error) {
      console.error(error);
      return { text: "Cloud Error: Verify connection or API quota." };
    }
  }
}

