            </>
          )}
          {disruption && (
            <div className="glass-panel rounded-xl p-4 border border-fresa/30 bg-fresa/5">
              <h3 className="text-xs font-black text-fresa flex items-center gap-2 mb-2"><Zap className="w-3 h-3" /> REALIDAD DISRUPTIVA LVL 9</h3>
